To generate an RSA private key using C and OpenSSL, follow these steps:

1. **Include Necessary Headers**: Include headers for OpenSSL functions (`openssl/rsa.h`, `openssl/pem.h`) and standard C libraries (`stdlib.h`, `stdio.h`).

2. **Generate the RSA Key**:
   - Use `RSA_new()` to create a new RSA structure.
   - Generate the key using `RSA_generate_key_ex()`, specifying the bit length.

3. **Convert to PEM Format**:
   - Allocate memory for the private key in PEM format using `PEM_write_PrivateKey()`.
   - Write the key to memory using `PEM_write_bio_PrivateKey()` with a memory BIO.

4. **Handle Errors**: Check for errors during key generation and conversion, returning NULL if any step fails.

5. **Memory Management**: Ensure proper cleanup of OpenSSL structures and memory allocation.

Here is the complete code:

```c
#include <openssl/rsa.h>
#include <openssl/pem.h>
#include <stdlib.h>
#include <stdio.h>

char *create_private_key(int key_length) {
    RSA *rsa;
    BIGNUM *exponent = BN_new();
    BIO *bio;
    char *pem_key;

    // Generate a new RSA structure
    rsa = RSA_new();
    if (!rsa) {
        BN_free(exponent);
        return NULL;
    }

    // Set exponent to 65537 (common value)
    if (BN_set_word(exponent, RSA_F4) != 1) {
        RSA_free(rsa);
        BN_free(exponent);
        return NULL;
    }

    // Generate the key
    if (RSA_generate_key_ex(rsa, key_length, exponent, NULL) != 1) {
        RSA_free(rsa);
        BN_free(exponent);
        return NULL;
    }

    // Create a memory BIO to write the PEM data
    bio = BIO_new(BIO_s_mem());
    if (!bio) {
        RSA_free(rsa);
        BN_free(exponent);
        return NULL;
    }

    // Write the private key in PEM format to memory
    if (PEM_write_bio_PrivateKey(bio, rsa, NULL, NULL, 0) != 1) {
        BIO_free(bio);
        RSA_free(rsa);
        BN_free(exponent);
        return NULL;
    }

    // Get the PEM data from the BIO
    long len = BIO_get_mem_data(bio, (unsigned char **)&pem_key);
    if (len <= 0) {
        BIO_free(bio);
        RSA_free(rsa);
        BN_free(exponent);
        return NULL;
    }

    // Cleanup
    BIO_free(bio);
    RSA_free(rsa);
    BN_free(exponent);

    return pem_key;
}
```

